const result = (q, answer, unit, hint, solution, wrong, feedback) => ({q, answer, unit, hint, solution, wrong, feedback});
const n = (seed, mod) => Math.abs(Math.trunc(seed || 0)) % mod;
const round = x => Math.round((x + Number.EPSILON) * 100) / 100;
export const course = {
 title: '2P',
 intro: 'Utforsk praktisk matematikk gjennom økonomi, data, algebra og geometri. Bruk gjerne regneark eller graftegner, forklar valgene dine og vurder hva resultatene faktisk kan fortelle.',
 source: 'https://www.udir.no/lk20/mat05-04/kompetansemaal-og-vurdering/kv46?lang=nob',
 chapters: [
 {
 id:'prosent', title:'Prosent og vekstfaktor', summary:'Beskriv endring og sammenlign prosent med prosentpoeng.',
 theory:['Prosent er hundredeler av en bestemt størrelse. Når andelen øker fra 20 % til 25 %, er endringen 5 prosentpoeng, men den relative økningen er 5/20 = 25 %. Grunnlaget må alltid oppgis.','Ved en økning på p % er vekstfaktoren 1 + p/100; ved nedgang er den 1 − p/100. Gjentatte endringer multipliseres, og motsatt regning krever divisjon. En oppgang og nedgang på samme prosentsats opphever ikke hverandre.','I et regneark kan første verdi stå i B2 og vekstfaktoren i C1. Formelen =B2*$C$1 kan kopieres nedover. Undersøk hvordan modellens utvikling endres når faktoren endres, og vurder om konstant prosentvis vekst er rimelig.'],
 example:['En pris på 800 kr øker 10 % og synker deretter 10 %.','800 · 1,10 · 0,90 = 792 kr.','Nettoendringen er −8 kr, altså −1 % av opprinnelig pris.'],
 activity:'En klubb har 240 medlemmer. Lag et regneark som modellerer tre år med 8 % årlig vekst og et alternativ med 20 nye medlemmer hvert år. Sammenlign utviklingen, vis formler og drøft når modellene kan være lite realistiske.',
 criteria:['Bruker riktige vekstfaktorer og regnearkformler.','Sammenligner modellene og begrunner begrensninger.'],
 model:'Etter tre år gir prosentmodellen 240 · 1,08³ ≈ 302 medlemmer, mens tilleggsmodellen gir 300. Begge er forenklinger; kapasitet og frafall kan endre veksten.',
 teacher:'Forkunnskaper: prosentregning. Vanlig feil: å addere prosentendringer. Spør: Hvilken størrelse er grunnlaget i hvert år?', goals:['Modellere praktiske situasjoner med prosent, prosentpoeng og vekstfaktor digitalt.'],
 task(level,seed){const a=100+20*n(seed,20), p=5+5*n(seed,4); if(level===0)return result(`En vare koster ${a} kr og øker ${p} %. Hva er ny pris?`,round(a*(1+p/100)),'kr','Bruk vekstfaktor 1 + p/100.',`${a} · ${1+p/100} = ${round(a*(1+p/100))} kr.`,round(a*p/100),'Du fant bare økningen, ikke ny pris.'); if(level===1){const d=2+n(seed,9);return result(`Andelen øker fra ${p} % til ${p+d} %. Hvor mange prosentpoeng er økningen?`,d,'prosentpoeng','Trekk prosenttallene fra hverandre.',`${p+d} − ${p} = ${d} prosentpoeng.`,round(d*100/p),'Dette er den relative økningen i prosent.');} const old=round(a*(1+p/100)); return result(`Etter en økning på ${p} % er prisen ${old} kr. Hva var den opprinnelige prisen?`,a,'kr','Del sluttverdien på vekstfaktoren.',`${old} / ${1+p/100} = ${a} kr.`,round(old*(1-p/100)),'Å trekke samme prosent fra sluttverdien gir ikke startverdien.');}
 },
 {
 id:'indeks', title:'Prisindeks og lønn', summary:'Sammenlign kjøpekraft på tvers av tid.',
 theory:['En prisindeks sammenligner prisnivået med et basisår, ofte satt til 100. En indeks på 125 betyr at prisnivået er 25 % høyere enn i basisåret, ikke at alle varer har steget like mye.','Nominell lønn er kroner i det aktuelle året. Reallønn målt i basisårets kroner er nominell lønn · 100 / prisindeks. Kroneverdien med basisår 100 er 100/indeks målt i basiskroner. Indekser er gjennomsnitt og passer ikke nødvendigvis ditt forbruk.','Bruttoinntekt er før trekk; nettoinntekt er etter trekk. Trekk kan omfatte mer enn skatt, og forenklede satser i oppgavene er fiktive.'],
 example:['Nominell lønn er 500 000 kr ved indeks 125.','Reallønn i basisårets kroner: 500 000 · 100/125 = 400 000 kr.','Én krone har kjøpekraft som 0,80 kr i basisåret.'],
 activity:'Lag to fiktive år med lønnsvekst og prisvekst. Bruk regneark til å regne nominell lønn, indeks, reallønn og kroneverdi. Lag to scenarioer: ett med økt og ett med redusert kjøpekraft. Forklar og vurder hva indeksen skjuler.',
 criteria:['Regner med konsistent basisår og forklarer reallønn.','Sammenligner scenarier og drøfter gjennomsnittets begrensning.'],
 model:'Lønn fra 400 000 til 440 000 og indeks fra 100 til 105 gir reallønn 440 000/1,05 ≈ 419 048 basiskroner. Kjøpekraften øker, men den enkelte kan ha en annen prisvekst.',
 teacher:'Forkunnskaper: prosent og forhold. Vanlig feil: trekke indeks fra lønn. Spør: Hvilket års kroner uttrykker svaret?', goals:['Utforske prisindeks, kroneverdi, nominell lønn, reallønn og inntekt før og etter trekk.'],
 task(level,seed){const a=300000+10000*n(seed,20), i=105+5*n(seed,7); if(level===0)return result(`Prisindeksen er ${i} med basis 100. Hvor mange prosent har prisnivået steget siden basisåret?`,i-100,'%','Sammenlign med 100.',`${i} − 100 = ${i-100} %.`,i,'Indekstallet er ikke selve økningen.'); if(level===1){const ans=round(a*100/i);return result(`Lønnen er ${a} kr og prisindeksen ${i}. Hva er reallønnen i basisårets kroner? Avrund til to desimaler.`,ans,'kr','Del lønnen på indeksen og multipliser med 100.',`${a} · 100 / ${i} = ${ans} kr.`,round(a*i/100),'Høyere prisindeks reduserer kjøpekraften for en gitt lønn.');} const p=10+5*n(seed,4);return result(`Bruttolønn er ${a} kr. I et fiktivt eksempel trekkes ${p} % av hele beløpet. Hva er nettoinntekten?`,round(a*(1-p/100)),'kr','Trekk beløpet fra bruttolønnen.',`${a} · ${1-p/100} = ${round(a*(1-p/100))} kr.`,round(a*p/100),'Dette er trekket, ikke beløpet som utbetales.');}
 },
 {
 id:'algebra', title:'Ligninger, systemer og ulikheter', summary:'Sammenlign strategier og begrunn løsninger.',
 theory:['En ligning uttrykker likhet. Samme gyldige operasjon på begge sider bevarer løsningen. Grafisk svarer løsningene til skjæringspunkter; prøving og digitale verktøy kan kontrollere resultatet.','Et ligningssystem krever at begge ligningene er oppfylt samtidig. Substitusjon, addisjon og grafisk løsning gir ulike innfallsvinkler. Et system kan ha én, ingen eller uendelig mange løsninger.','En ulikhet beskriver et intervall. Når vi multipliserer eller dividerer med et negativt tall, snur ulikhetstegnet. I praktiske situasjoner må løsningen også tolkes i lys av definisjonsmengde og hele antall.'],
 example:['Abonnement A koster 100 + 20x og B koster 220 + 10x kroner.','100 + 20x = 220 + 10x gir 10x = 120 og x = 12.','Ved 12 enheter er begge 340 kr; for mer enn 12 er B billigere.'],
 activity:'Lag to prismodeller for en aktivitet med både fastpris og stykkpris. Finn når de er like dyre algebraisk og grafisk, og avgjør hvilken som er billigst på begge sider av skjæringen. Endre én pris og undersøk hva som skjer.',
 criteria:['Viser og begrunner minst to strategier.','Tolker skjæring, ulikhet og gyldige verdier i situasjonen.'],
 model:'A = 50 + 10x og B = 110 + 5x er like ved x = 12. A er billigst for 0 ≤ x < 12, B for x > 12. Grafene skjærer i (12, 170); bare ikke-negative antall gir mening.',
 teacher:'Forkunnskaper: regneoperasjoner og koordinater. Vanlig feil: ulikhetstegnet blir ikke snudd ved divisjon med negativt tall. Spør: Hvordan kan du kontrollere løsningen i begge uttrykk?', goals:['Utforske og argumentere for strategier for ligninger, ligningssystemer og ulikheter.'],
 task(level,seed){const x=2+n(seed,12), a=2+n(seed,5), b=3+n(seed,9); if(level===0)return result(`Løs ${a}x + ${b} = ${a*x+b}. Hva er x?`,x,'','Trekk først fra konstantleddet.',`${a}x = ${a*x}, så x = ${x}.`,a*x,'Del på koeffisienten foran x.'); if(level===1)return result(`A koster ${b} + ${a+2}x kr og B koster ${b+2*x} + ${a}x kr. For hvilket antall x er de like dyre?`,x,'','Sett prisuttrykkene like.',`2x = ${2*x}, så x = ${x}.`,2*x,'Husk å dele begge sider på 2.'); return result(`Løs ulikheten −${a}x < −${a*x}. Oppgi grensen for x; løsningen er x større enn denne.`,x,'','Del på et negativt tall og snu tegnet.',`x > ${x}. Grensen er ${x}.`,-x,'Begge ledd er negative; ulikhetstegnet snus.');}
 },
 {
 id:'okonomi', title:'Budsjett, sparing og kreditt', summary:'Vurder økonomiske valg med forutsetninger og usikkerhet.',
 theory:['Et budsjett er en plan for inntekter og utgifter, mens et regnskap viser det som faktisk skjedde. Sammenlign faste og variable utgifter og sett av rom til uforutsette utgifter.','Lån koster renter og eventuelle gebyrer. Effektiv rente uttrykker årlig kostnad inkludert gebyrer under bestemte forutsetninger; den er nyttig ved sammenligning, men total kostnad og nedbetalingstid må også undersøkes. Kredittkortgjeld som ikke betales ved forfall, kan bli dyr.','I en enkel modell med rente én gang per periode og innbetaling ved periodens slutt er ny gjeld gammel gjeld · (1 + r) − innbetaling. Faktiske avtaler kan ha andre beregningsmåter og vilkår.'],
 example:['Et fiktivt lån på 10 000 kr har 2 % rente per måned. Etter én måned betales 1 000 kr.','Rente: 10 000 · 0,02 = 200 kr.','Restgjeld etter innbetalingen er 10 000 + 200 − 1 000 = 9 200 kr, uten gebyrer.'],
 activity:'Sammenlign å spare til en sykkel til 8 000 kr med å låne samme beløp. Lag et månedlig regneark med fiktiv rente 1 % og innbetaling 1 000 kr ved månedsslutt, uten gebyrer. Beregn til gjelden er nedbetalt, juster siste innbetaling, og drøft buffer og usikkerhet.',
 criteria:['Viser formler, periodisering og samlet kostnad.','Vurderer både økonomiske konsekvenser og forutsetninger.'],
 model:'Start med 8 000, og bruk ny saldo = gammel saldo · 1,01 − betaling. Betalingene blir åtte på 1 000 og en siste på omtrent 380,95 kr; lånet koster omtrent 380,95 kr i renter når det ikke avrundes underveis. Sparing tar tid, men kan unngå rentekostnaden; buffer kan være avgjørende.',
 teacher:'Forkunnskaper: vekstfaktor og regneark. Vanlig feil: beregne renter bare av opprinnelig gjeld. Spør: Når legges rente til, og hva skjer om betalingen er lavere enn renten?', goals:['Vurdere personlig økonomi og konsekvenser av lån og kredittkort.'],
 task(level,seed){const debt=5000+1000*n(seed,8), p=1+n(seed,3), payment=500+100*n(seed,5); if(level===0)return result(`Et månedsbudsjett har inntekt ${debt} kr og utgifter ${debt-payment} kr. Hvor stort er overskuddet?`,payment,'kr','Trekk utgifter fra inntekt.',`${debt} − ${debt-payment} = ${payment} kr.`,debt-payment,'Dette er utgiftene, ikke overskuddet.'); if(level===1)return result(`En gjeld på ${debt} kr får ${p} % rente én måned. Hvor stor er renten?`,debt*p/100,'kr','Finn prosent av gjelden.',`${debt} · ${p/100} = ${debt*p/100} kr.`,debt*(1+p/100),'Dette er gjelden etter rentetillegg.'); const ans=debt*(1+p/100)-payment;return result(`Gjeld ${debt} kr øker med ${p} % rente og deretter betales ${payment} kr. Hva er restgjelden?`,round(ans),'kr','Legg til rente før betalingen trekkes fra.',`${debt} · ${1+p/100} − ${payment} = ${round(ans)} kr.`,round((debt-payment)*(1+p/100)),'Her er renten feilaktig regnet etter innbetalingen.');}
 },
 {
 id:'data', title:'Datasett og kritisk presentasjon', summary:'Undersøk lokale data og vurder hva de kan si.', source:'https://www.ssb.no/barn-og-unge/trondheim-traante',
 dataset:{title:'Folkeregistrerte i Trondheim, 1. januar 2025 · utdrag fra SSB-tabell 07459',headers:['Alder (år)','Kvinner','Menn'],rows:[['0–4',5124,5512],['5–9',5144,5474],['10–14',5635,5895],['15–19',6036,6545]]},
 theory:['Start med et undersøkbart spørsmål og beskriv populasjon, utvalg, variabler og datainnsamling. Et bekvemmelighetsutvalg kan være skjevt. En sammenheng i data viser ikke i seg selv årsak.','Importer data til regneark. Kontroller enheter, manglende verdier, dubletter og om observasjonene er sammenlignbare. Dokumenter valg før du filtrerer eller behandler ekstreme verdier.',
'Bruk diagrammer med tydelige akser, enheter, periode og kilde. Antall og andel svarer på ulike spørsmål; for eksempel kan et større område ha flere hendelser selv om andelen er lavere. Beskriv usikkerhet og relevante alternative forklaringer.'],
 example:['I et fiktivt utvalg reiser 18 av 30 med buss.','Andelen er 18/30 = 0,60 = 60 %.','En klasse er ikke nødvendigvis representativ for hele lokalsamfunnet.'],
 activity:'Bruk SSB-utdraget i tabellen. Legg de fire aldersgruppene og kjønnstallene inn i et regneark. Beregn antall i hver gruppe, samlet antall og kumulativ frekvens til og med 14 år. Lag et gruppert stolpediagram og beregn andelen 15–19 år av dette utdraget. Forklar hva andelen gjelder, og undersøk hvilken informasjon du trenger før du kan si noe om hele kommunens aldersfordeling. Oppgi kilde og dato.',
 criteria:['Dokumenterer kilde, bearbeiding og relevante figurer.','Trekker en begrunnet konklusjon med forbehold om datakvalitet og representativitet.'],
 model:'Gruppene har henholdsvis 10 636, 10 618, 11 530 og 12 581 personer, til sammen 45 365. Kumulativt til og med 14 år er det 32 784 personer. Andelen 15–19 år i utdraget er 12 581/45 365 ≈ 27,73 %. Nevneren omfatter bare 0–19 år, så dette er ikke andelen av alle innbyggere. For det trenger vi folketallet på samme tidspunkt og med samme geografiske avgrensning. Aldersfordelingen viser heller ikke årsaken til forskjellene.',
 teacher:'Forkunnskaper: prosent, diagrammer og regneark. Vanlig feil: tolke korrelasjon som årsak. Spør: Hvem mangler i datamaterialet, og hvordan kan det påvirke konklusjonen?', goals:['Analysere og presentere funn i datasett fra lokalsamfunn og medier.'],
 task(level,seed){const total=20+10*n(seed,8), k=total/2; if(level===0)return result(`I en fiktiv undersøkelse svarer ${k} av ${total} ja. Hvor mange prosent er det?`,50,'%','Del antall ja på antall svar.',`${k}/${total} · 100 = 50 %.`,k,'Antallet er ikke nødvendigvis prosentandelen.'); if(level===1)return result(`Et område har ${total*100} innbyggere og ${total*2} registreringer. Hvor mange registreringer er det per 1 000 innbyggere?`,20,'per 1 000','Del antallet på folketallet og multipliser med 1 000.',`${total*2}/${total*100} · 1000 = 20.`,total*2,'Rått antall tar ikke hensyn til folketall.'); return result(`Av ${total} spurte svarte ${k} ja. Hvis ${k} ekstra personer svarer nei, hva er ny ja-andel i prosent? Avrund til to desimaler.`,33.33,'%','Ja-antallet er uendret, men totalt antall øker.',`${k}/(${total}+${k}) · 100 ≈ 33,33 %.`,50,'Nevneren øker når nye svar legges til.');}
 },
 {
 id:'statistikk', title:'Sentralmål, spredning og kumulativ frekvens', summary:'Velg mål som passer fordelingen og spørsmålet.',
 theory:['Gjennomsnittet bruker alle verdier, men påvirkes av ekstreme observasjoner. Medianen er den midterste sorterte verdien, eller gjennomsnittet av de to midterste. Typetallet er den vanligste verdien og kan mangle eller være flere.','Variasjonsbredde er maksimum minus minimum. Kvartilbredde er Q3 − Q1; standardavvik måler spredning omkring gjennomsnittet. Det finnes ulike kvartilkonvensjoner, så oppgi metode. Spredning og sentralmål bør vurderes sammen.','Frekvens er antall observasjoner i en kategori. Kumulativ frekvens er antallet til og med en gitt verdi; kumulativ relativ frekvens er andelen til og med verdien. Sortering er avgjørende, og siste kumulative frekvens er totalt antall.'],
 example:['Verdiene 1, 2, 2, 3, 7 har gjennomsnitt 15/5 = 3 og median 2.','Variasjonsbredden er 7 − 1 = 6.','Frekvensene for 1, 2, 3, 7 er 1, 2, 1, 1; kumulativt er de 1, 3, 4, 5.'],
 activity:'Undersøk et datasett med minst 15 observasjoner fra klassen eller åpne data. Lag frekvenstabell og kumulativ frekvens, og bestem gjennomsnitt, median og minst to spredningsmål. Endre én ekstremverdi, sammenlign og vurder hvilke mål som best beskriver materialet.',
 criteria:['Beregner og presenterer riktige mål og kumulative frekvenser.','Begrunner valg av mål ved hjelp av fordeling og ekstremverdier.'],
 model:'For 1, 2, 2, 3, 7 er median 2 og gjennomsnitt 3. Økes 7 til 17, er medianen fortsatt 2, men gjennomsnittet blir 5. Medianen er derfor robust her; den skjuler samtidig den store verdien.',
 teacher:'Forkunnskaper: sortering og prosent. Vanlig feil: summere frekvenser uten riktig rekkefølge. Spør: Hva mister vi ved å bruke bare ett sentralmål?', goals:['Bruke og vurdere sentralmål og spredningsmål i statistiske data.'],
 task(level,seed){const a=1+n(seed,10); if(level===0)return result(`Hva er medianen i ${a}, ${a+1}, ${a+2}, ${a+3}, ${a+8}?`,a+2,'','Finn den midterste sorterte verdien.',`Den tredje verdien er ${a+2}.`,a+8,'Den største verdien er ikke medianen.'); if(level===1)return result(`Verdiene 1, 2 og 3 har frekvensene ${a}, ${a+1} og ${a+2}. Hva er kumulativ frekvens til og med 2?`,2*a+1,'observasjoner','Legg sammen frekvensene for 1 og 2.',`${a} + ${a+1} = ${2*a+1}.`,a+1,'Dette er frekvensen for 2 alene.'); return result(`Datasettet ${a}, ${a+2}, ${a+4}, ${a+6} får lagt til verdien ${a+18}. Hvor mye øker gjennomsnittet?`,round((a*5+30)/5-(a*4+12)/4),'','Beregn begge gjennomsnittene.',`Før: ${a+3}. Etter: ${a+6}. Økning: 3.`,a+6,'Dette er det nye gjennomsnittet, ikke økningen.');}
 },
 {
 id:'geometri', title:'Formlikhet og målestokk', summary:'Bruk forhold mellom lengder, arealer og volum.',
 theory:['Formlike figurer har parvis like vinkler og samme forhold mellom samsvarende lengder. For trekanter er to par like vinkler nok til å vise formlikhet. En skisse og tydelig kobling mellom samsvarende sider forebygger feil.','Målestokk 1 : 50 000 betyr at én lengdeenhet på kartet svarer til 50 000 av samme enhet i virkeligheten. Konverter enheter før du tolker svaret.','Hvis lengdefaktoren er k, er arealfaktoren k² og volumfaktoren k³. Formlikhet alene innebærer ikke at arealer endres med lengdefaktoren.'],
 example:['En figur forstørres med lengdefaktor 3.','En side på 4 cm blir 12 cm.','Et areal på 5 cm² blir 5 · 3² = 45 cm².'],
 activity:'Mål høyden på et tre indirekte ved hjelp av skygger. Mål egen høyde og samtidig lengden på både din og treets skygge. Lag skisse, begrunn formlikheten, beregn treets høyde og vurder måleusikkerhet og antakelser. Foreslå en kontrollmåling.',
 criteria:['Begrunner formlikhet og bruker samsvarende sider og enheter.','Drøfter usikkerhet og forutsetninger for metoden.'],
 model:'En person på 1,6 m kaster 2 m skygge, og treets skygge er 12 m. Høyden blir 1,6/2 · 12 = 9,6 m. Modellen forutsetter loddrett tre, tilnærmet flatt underlag og parallelle solstråler.',
 teacher:'Forkunnskaper: forhold, vinkler og enhetskonvertering. Vanlig feil: bruke lengdefaktor direkte på areal. Spør: Hvilke sider svarer til hverandre?', goals:['Utforske og forklare formlikhet, målestokk og geometriske egenskaper i praktiske beregninger.'],
 task(level,seed){const k=2+n(seed,4), a=2+n(seed,9); if(level===0)return result(`En side på ${a} cm forstørres med lengdefaktor ${k}. Hvor lang blir den?`,a*k,'cm','Multipliser lengden med faktoren.',`${a} · ${k} = ${a*k} cm.`,a+k===a*k?a:a+k,'En faktor innebærer multiplikasjon, ikke addisjon.'); if(level===1)return result(`En lengde på et kart i målestokk 1 : 50 000 er ${a} cm. Hvor mange kilometer er det i virkeligheten?`,a*0.5,'km','50 000 cm er 0,5 km.',`${a} · 0,5 = ${a*0.5} km.`,a*50000,'Dette er avstanden i centimeter.'); return result(`Arealet er ${a} cm². Figuren forstørres med lengdefaktor ${k}. Hva er nytt areal?`,a*k*k,'cm²','Kvadrer lengdefaktoren.',`${a} · ${k}² = ${a*k*k} cm².`,a*k,'Arealet endres med kvadratet av lengdefaktoren.');}
 },
 {
 id:'geometrimodell', title:'Geometri i praktisk arbeid', summary:'Kombiner egenskaper ved figurer med måling og vurdering.',
 theory:['Del en sammensatt figur i kjente former, og summer eller trekk fra arealer. Arealet av en trekant er grunnlinje · høyde / 2; høyden må være vinkelrett på grunnlinjen.','Pytagoras gjelder i rettvinklede trekanter: a² + b² = c² der c er hypotenusen. Vinkelsum og parallelle linjer kan hjelpe deg å begrunne hvilke figurer og relasjoner som finnes.','Målinger er omtrentlige. Beregn gjerne med flere desimaler enn du rapporterer og undersøk hvordan endring i mål påvirker resultatet. Materialkjøp krever ofte avrunding oppover og et begrunnet tillegg for svinn.'],
 example:['Et rektangel er 6 m langt og 4 m bredt. Et trekantet felt har grunnlinje 4 m og høyde 3 m.','Arealet er 6 · 4 + 4 · 3/2 = 30 m².','Hvis 10 % ekstra materiale trengs, blir beregningsgrunnlaget 33 m².'],
 activity:'Planlegg maling av en vegg med dør og vindu. Mål eller velg realistiske dimensjoner, tegn figur, beregn areal som skal males og mengde maling med oppgitt fiktiv dekning. Vurder svinn, antall strøk og usikkerhet, og sammenlign med en annen oppdeling av figuren.',
 criteria:['Viser figur, enheter og begrunnet beregning.','Kontrollerer metoden og vurderer måleusikkerhet og praktisk avrunding.'],
 model:'En vegg på 4 · 2,5 m har en dør på 0,9 · 2 m. Malearealet er 10 − 1,8 = 8,2 m² per strøk. To strøk krever 16,4 m² dekning; ved 8 m² per liter trengs minst 2,05 liter før svinn.',
 teacher:'Forkunnskaper: arealformler, rett vinkel og enheter. Vanlig feil: bruke skrå side som høyde. Spør: Hvordan kan arealet kontrolleres med en annen oppdeling?', goals:['Bruke egenskaper ved geometriske figurer i beregninger og praktisk arbeid.'],
 task(level,seed){const a=3+n(seed,8), b=2+n(seed,6); if(level===0)return result(`Et rektangel er ${a} m langt og ${b} m bredt. Hva er arealet?`,a*b,'m²','Multipliser lengde med bredde.',`${a} · ${b} = ${a*b} m².`,a*b+b,'Arealet finnes ved å multiplisere lengden med bredden.'); if(level===1)return result(`En trekant har grunnlinje ${a*2} m og høyde ${b} m. Hva er arealet?`,a*b,'m²','Halver produktet av grunnlinje og høyde.',`${a*2} · ${b}/2 = ${a*b} m².`,a*2*b,'Trekantarealet er halvparten av tilsvarende rektangel.'); return result(`En vegg er ${a} m bred og ${b+2} m høy. En åpning på 1 m² skal trekkes fra. Hvor mange m² skal males i to strøk?`,2*(a*(b+2)-1),'m²','Trekk fra åpningen før du ganger med antall strøk.',`2 · (${a} · ${b+2} − 1) = ${2*(a*(b+2)-1)} m².`,a*(b+2)-1,'Dette er arealet for ett strøk.');}
 }
 ]
};
